  { id: "u3-side", unit: "3", kind: "הגדרה", title: "התקפת ערוץ צדדי (Side-Channel)", body: "הפקת מידע ממדידת זמן ריצה (Timing Attack). השוואת סיסמה עם strcmp יוצאת מוקדם; יש להשתמש בהשוואה בזמן קבוע." },
  { id: "u3-fuzz", unit: "3", kind: "טריק", title: "פאזינג (Fuzzing)", body: "הזרמת קלטים אקראיים ומשובשים לגילוי קריסות ומקרי קצה חריגים בתוכנית." },
  { id: "u3-vptr", unit: "3", kind: "מלכודת", title: "דריסת vptr ו־Vtable", body: "דריסת vptr של אובייקט משפיעה עליו בלבד. שינוי כניסה ב־Vtable המשותפת משפיע על כל מופעי המחלקה (נושא בחינה מ־2025ג)!" },
  { id: "u3-priv-mem", unit: "3", kind: "מלכודת", title: "private אינו חומת זיכרון", body: "הרשאות גישה נאכפות בקומפילציה בלבד. גישה ישירה לזיכרון וכתיבה גולמית עוקפות כל הגדרת private." },
  { id: "u3-cfi", unit: "3", kind: "הגדרה", title: "שלמות זרימת בקרה (CFI)", body: "אימות בזמן ריצה שקפיצות עקיפות מגיעות אך ורק ליעדים לגיטימיים שהוגדרו מראש בקומפילציה." },
  { id: "u3-static", unit: "3", kind: "הגדרה", title: "ניתוח סטטי (Static Analysis)", body: "בדיקת קוד המקור ללא הרצה (cppcheck, התראות קומפיילר). מוצא שגיאות תחביר ודפוסים פגיעים." },
  { id: "u3-valg", unit: "3", kind: "הגדרה", title: "ניתוח דינמי (Valgrind)", body: "הרצת קוד מהודר בסביבה מבוקרת. מאתר בזמן אמת דליפות זיכרון, חריגות מגבול חוצץ ושימוש אחרי שחרור." },
  { id: "u3-heap-adj", unit: "3", kind: "לזכור", title: "שכן בערימה", body: "גלישת חוצץ בערימה יכולה לדרוס מצביע פונקציה או vptr של הבלוק השכן שהוקצה מיד אחריו." },
  { id: "u3-fields", unit: "3", kind: "מלכודת", title: "גלישה בין שדות במבנה", body: "כתיבה עודפת לחוצץ זולגת לשדה הבא באותו מבנה נתונים. אם השדה הוא מצביע, הכתיבה הבאה תהיה לכתובת שרירותית." }
